export async function manuallyRecoverReviewRun(
  env: Env,
  reviewId: string,
  reviewGithubToken: string | null,
  openrouterApiKey: string | null
): Promise<{ action: 'requeued' | 'failed'; review: Awaited<ReturnType<typeof getReviewRun>> }> {
